        pytester.makepyfile(
            test_class="""
            class TestWithSetupClass:
                setup_called = False

                @classmethod
                def setup_class(cls):
                    cls.setup_called = True

                def test_method(self):
                    assert self.setup_called
        """
        )

        # Hook into collection to verify fixture was injected
        pytester.makeconftest("""
