@pytest.mark.parametrize("orientation, inverted, extend", [
    ("vertical", True, "both"),
    ("vertical", True, "min"),
    ("vertical", True, "max"),
    ("vertical", True, "neither"),
    ("horizontal", True, "both"),
    ("horizontal", True, "min"),
    ("horizontal", True, "max"),
    ("horizontal", True, "neither"),
    ("vertical", False, "both"),
    ("vertical", False, "min"),
])
def test_draw_all_paths(orientation, inverted, extend):
    # Set the appropriate rcParam for minor ticks
    rc_context = {}
    if orientation == "vertical":
        rc_context['ytick.minor.visible'] = True
    else:
        rc_context['xtick.minor.visible'] = True

    with plt.rc_context(rc_context):
        fig, ax = plt.subplots()

        # Create a contour plot with filled=True
        x = y = np.arange(-3.0, 3.01, 0.025)
        X, Y = np.meshgrid(x, y)
        Z = np.exp(-X**2 - Y**2)
        cs = ax.contourf(X, Y, Z, extend=extend)

        # Create the colorbar
        cbar = Colorbar(ax, mappable=cs, orientation=orientation, extend=extend)

        # Invert the axis if needed
        if inverted:
            if orientation == "vertical":
                cbar.ax.invert_yaxis()
            else:
                cbar.ax.invert_xaxis()

        # Call _draw_all to trigger the execution path
        cbar._draw_all()

        # Check axis limits
        if orientation == "vertical":
            ylim = cbar.ax.get_ylim()
            if inverted:
                assert ylim[0] > ylim[1]
            else:
                assert ylim[0] < ylim[1]
        else:
            xlim = cbar.ax.get_xlim()
            if inverted:
                assert xlim[0] > xlim[1]
            else:
                assert xlim[0] < xlim[1]

        # Check extend patches
        expected_patches = 0
        if extend in ["min", "both"]:
            expected_patches += 1
        if extend in ["max", "both"]:
            expected_patches += 1
        assert len(cbar._extend_patches) == expected_patches

        # Check minor ticks
        if orientation == "vertical":
            assert not isinstance(cbar.ax.yaxis.get_minor_locator(), ticker.NullLocator)
        else:
            assert not isinstance(cbar.ax.xaxis.get_minor_locator(), ticker.NullLocator)
