        class MockCheckURLMixin(CheckURLMixin):
            def __init__(self, pattern):
                self._regex = pattern
                self._regex_dict = {}
                self.name = 'test-pattern'

            def describe(self):
                return "'test-pattern'"

            @property
            def regex(self):
                class MockPattern:
                    def __init__(self, pattern):
                        self.pattern = pattern
                return MockPattern(self._regex)

        # Test all variants that should trigger the warning
        warning_patterns = ['/', '^/', '^\\/']
        for prefix in warning_patterns:
            with self.subTest(pattern=prefix + 'test'):
                pattern = MockCheckURLMixin(prefix + 'test')
                warnings = pattern._check_pattern_startswith_slash()

                self.assertEqual(len(warnings), 1)
                self.assertIsInstance(warnings[0], Warning)
                self.assertEqual(warnings[0].id, 'urls.W002')
                self.assertIn("Your URL pattern 'test-pattern' has a route beginning with a '/'.", str(warnings[0]))

