def test_init_subclass_wrapping_behavior():
    """Test _SetOutputMixin.__init_subclass__ wrapping behavior for different method definitions.

    This test covers:
      - Path 3: Both transform and fit_transform defined in the class -> both wrapped
      - Path 4: transform defined in class, fit_transform inherited from base -> only transform wrapped
    """
    pd = pytest.importorskip("pandas")
    X = np.array([[1, 2], [3, 4]])

    # Path 3: Both methods defined in the class
    class EstimatorWithBoth(_SetOutputMixin):
        def fit(self, X, y=None):
            self.n_features_in_ = X.shape[1]
            return self

        def transform(self, X, y=None):
            return X

        def fit_transform(self, X, y=None):
            return X

        def get_feature_names_out(self, input_features=None):
            return np.array([f"X{i}" for i in range(self.n_features_in_)])

    est_both = EstimatorWithBoth().fit(X)
    est_both.set_output(transform="pandas")
    X_trans = est_both.transform(X)
    assert isinstance(X_trans, pd.DataFrame)
    X_fit_trans = est_both.fit_transform(X)
    assert isinstance(X_fit_trans, pd.DataFrame)

    # Path 4: transform defined in class, fit_transform inherited from base
    class BaseWithFitTransform:
        def fit_transform(self, X, y=None):
            return X

    class EstimatorWithTransformOnly(_SetOutputMixin, BaseWithFitTransform):
        def fit(self, X, y=None):
            self.n_features_in_ = X.shape[1]
            return self

        def transform(self, X, y=None):
            return X

        def get_feature_names_out(self, input_features=None):
            return np.array([f"X{i}" for i in range(self.n_features_in_)])

    est_trans = EstimatorWithTransformOnly().fit(X)
    est_trans.set_output(transform="pandas")
    X_trans = est_trans.transform(X)
    assert isinstance(X_trans, pd.DataFrame)
    X_fit_trans = est_trans.fit_transform(X)
    # fit_transform is not wrapped (inherited method), so returns numpy array
    assert isinstance(X_fit_trans, np.ndarray)
