def test_load_plugin_commands(monkeypatch):
    """Test _load_plugin_commands covers all execution paths:
    - Early return when commands already loaded
    - Python >= 3.10 with multiple entry points
    - Python >= 3.10 with single entry point
    - Python >= 3.10 with no entry points
    - Python < 3.10 with multiple entry points
    - Python < 3.10 with single entry point
    - Python < 3.10 with no entry points
    """
    # Test Path 1: Already loaded, should return early
    cli = FlaskGroup()
    cli._loaded_plugin_commands = True
    initial_commands = set(cli.list_commands(None))
    cli._load_plugin_commands()
    assert cli._loaded_plugin_commands is True
    assert set(cli.list_commands(None)) == initial_commands

    # Test Paths 2-4: Python >= 3.10
    for num_points, expected_count in [(2, 2), (1, 1), (0, 0)]:
        cli = FlaskGroup()
        monkeypatch.setattr(sys, "version_info", (3, 11))

        # Setup mock entry points
        class MockEntryPoint:
            def __init__(self, idx):
                self.name = f"cmd{idx}"
            def load(self):
                @click.command(self.name)
                def cmd():
                    pass
                return cmd

        class MockMetadata:
            @staticmethod
            def entry_points(group):
                if group == "flask.commands":
                    return [MockEntryPoint(i) for i in range(num_points)]
                return []

        monkeypatch.setitem(sys.modules, "importlib.metadata", MockMetadata)

        # Verify command loading
        initial_commands = set(cli.list_commands(None))
        cli._load_plugin_commands()
        assert cli._loaded_plugin_commands is True
        new_commands = set(cli.list_commands(None)) - initial_commands
        assert len(new_commands) == expected_count
        assert new_commands == {f"cmd{i}" for i in range(expected_count)}

    # Test Paths 5-7: Python < 3.10
    for num_points, expected_count in [(2, 2), (1, 1), (0, 0)]:
        cli = FlaskGroup()
        monkeypatch.setattr(sys, "version_info", (3, 9))

        # Setup mock entry points
        class MockEntryPoint:
            def __init__(self, idx):
                self.name = f"cmd{idx}"
            def load(self):
                @click.command(self.name)
                def cmd():
                    pass
                return cmd

        class MockMetadata:
            @staticmethod
            def entry_points(group):
                if group == "flask.commands":
                    return [MockEntryPoint(i) for i in range(num_points)]
                return []

        monkeypatch.setitem(sys.modules, "importlib_metadata", MockMetadata)

        # Verify command loading
        initial_commands = set(cli.list_commands(None))
        cli._load_plugin_commands()
        assert cli._loaded_plugin_commands is True
        new_commands = set(cli.list_commands(None)) - initial_commands
        assert len(new_commands) == expected_count
        assert new_commands == {f"cmd{i}" for i in range(expected_count)}
