def test_constructor_postprocessors():
    # Test Path 1: One argument with two postprocessor mappings
    class TestObj1(Basic):
        pass
    class TestArg1(Basic):
        _constructor_postprocessor_mapping = {
            TestArg1: {'TestObj1': [lambda x: TestObj1(x.args[0] + (1,))]}
        }

    Basic._constructor_postprocessor_mapping = {
        TestArg1: {'TestObj1': [
            lambda x: TestObj1(x.args[0] + (1,)),
            lambda x: TestObj1(x.args[0] + (2,))
        ]}
    }

    obj1 = TestObj1((0,))
    arg1 = TestArg1()
    result1 = TestObj1._exec_constructor_postprocessors(TestObj1(arg1))
    assert result1.args[0] == (0, 1, 2)

    # Test Path 2: Two arguments, each with two postprocessor mappings
    class TestObj2(Basic):
        pass
    class TestArg2a(Basic):
        _constructor_postprocessor_mapping = {
            TestArg2a: {'TestObj2': [lambda x: TestObj2(x.args[0] + (1,))]}
        }
    class TestArg2b(Basic):
        _constructor_postprocessor_mapping = {
            TestArg2b: {'TestObj2': [lambda x: TestObj2(x.args[0] + (3,))]}
        }

    Basic._constructor_postprocessor_mapping = {
        TestArg2a: {'TestObj2': [
            lambda x: TestObj2(x.args[0] + (1,)),
            lambda x: TestObj2(x.args[0] + (2,))
        ]},
        TestArg2b: {'TestObj2': [
            lambda x: TestObj2(x.args[0] + (3,)),
            lambda x: TestObj2(x.args[0] + (4,))
        ]}
    }

    result2 = TestObj2._exec_constructor_postprocessors(TestObj2(TestArg2a(), TestArg2b()))
    assert result2.args[0] == (1, 2, 3, 4)

    # Test Path 3: Two arguments, each with one postprocessor mapping
    class TestObj3(Basic):
        pass

    Basic._constructor_postprocessor_mapping = {
        TestArg2a: {'TestObj3': [lambda x: TestObj3(x.args[0] + (1,))]},
        TestArg2b: {'TestObj3': [lambda x: TestObj3(x.args[0] + (3,))]}
    }

    result3 = TestObj3._exec_constructor_postprocessors(TestObj3(TestArg2a(), TestArg2b()))
    assert result3.args[0] == (1, 3)

    # Test Path 4: Two arguments, first has mapping, second doesn't
    class TestArg4(Basic):
        pass  # No _constructor_postprocessor_mapping

    Basic._constructor_postprocessor_mapping = {
        TestArg2a: {'TestObj3': [lambda x: TestObj3(x.args[0] + (1,))]}
    }

    result4 = TestObj3._exec_constructor_postprocessors(TestObj3(TestArg2a(), TestArg4()))
    assert result4.args[0] == (1,)

    # Test Path 5: Two arguments, first has mapping, second raises TypeError
    class TestArg5(Basic):
        @property
        def _constructor_postprocessor_mapping(self):
            raise TypeError("Test error")

    Basic._constructor_postprocessor_mapping = {
        TestArg2a: {'TestObj3': [lambda x: TestObj3(x.args[0] + (1,))]}
    }

    result5 = TestObj3._exec_constructor_postprocessors(TestObj3(TestArg2a(), TestArg5()))
    assert result5.args[0] == (1,)

    # Test Path 6: One argument with one mapping, two postprocessors for current class
    class TestObj6(Basic):
        pass

    Basic._constructor_postprocessor_mapping = {
        TestArg2a: {'TestObj6': [
            lambda x: TestObj6(x.args[0] + (1,)),
            lambda x: TestObj6(x.args[0] + (2,))
        ]}
    }

    result6 = TestObj6._exec_constructor_postprocessors(TestObj6((0,)))
    assert result6.args[0] == (0, 1, 2)

    # Test Path 7: One argument with one mapping, one postprocessor for current class
    class TestObj7(Basic):
        pass

    Basic._constructor_postprocessor_mapping = {
        TestArg2a: {'TestObj7': [lambda x: TestObj7(x.args[0] + (1,))]}
    }

    result7 = TestObj7._exec_constructor_postprocessors(TestObj7((0,)))
    assert result7.args[0] == (0, 1)

    # Test Path 8: One argument with one mapping, no postprocessors for current class
    class TestObj8(Basic):
        pass

    Basic._constructor_postprocessor_mapping = {
        TestArg2a: {'DifferentClass': [lambda x: TestObj8(x.args[0] + (1,))]}
    }

    result8 = TestObj8._exec_constructor_postprocessors(TestObj8((0,)))
    assert result8.args[0] == (0,)

    # Test Path 9: Two arguments, first has no mappings, second has two
    class TestObj9(Basic):
        pass

    Basic._constructor_postprocessor_mapping = {
        TestArg2b: {'TestObj9': [
            lambda x: TestObj9(x.args[0] + (3,)),
            lambda x: TestObj9(x.args[0] + (4,))
        ]}
    }

    result9 = TestObj9._exec_constructor_postprocessors(TestObj9(TestArg4(), TestArg2b()))
    assert result9.args[0] == (3, 4)

    # Test Path 10: Two arguments, first has no mappings, second has one
    class TestObj10(Basic):
        pass

    Basic._constructor_postprocessor_mapping = {
        TestArg2b: {'TestObj10': [lambda x: TestObj10(x.args[0] + (3,))]}
    }

    result10 = TestObj10._exec_constructor_postprocessors(TestObj10(TestArg4(), TestArg2b()))
    assert result10.args[0] == (3,)

    # Clean up
    Basic._constructor_postprocessor_mapping = {}
